import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"No More Expired Certificates Simplifying TLS Management in Ceph with certmgr","description":"","frontmatter":{"title":"No More Expired Certificates Simplifying TLS Management in Ceph with certmgr","date":"2026-07-10T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","Cephadm","安全性","监控","自动化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/No_More_Expired_Certificates_Simplifying_TLS_Management_in_Ceph_with_certmgr.md","filePath":"posts/2026/No_More_Expired_Certificates_Simplifying_TLS_Management_in_Ceph_with_certmgr.md","lastUpdated":null}'),s={name:"posts/2026/No_More_Expired_Certificates_Simplifying_TLS_Management_in_Ceph_with_certmgr.md"};function i(l,e,o,p,d,c){return a(),r("div",null,[...e[0]||(e[0]=[n(`<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次分享由 IBM 工程师 Rudwan 主讲，他同时担任 Cephadm 的组件负责人。主题聚焦于 Ceph 集群中 TLS 证书管理的痛点，以及为此引入的新子组件 <strong>certmgr（cert manager）</strong> 如何系统性地解决这些问题。certmgr 作为 Cephadm 的子模块，在 Tentacle 版本中部分引入，计划在 Squid 版本中完整落地。</p><h2 id="当前-tls-证书管理的痛点" tabindex="-1">当前 TLS 证书管理的痛点 <a class="header-anchor" href="#当前-tls-证书管理的痛点" aria-label="Permalink to &quot;当前 TLS 证书管理的痛点&quot;">​</a></h2><p>在生产集群中管理证书并不简单，Cephadm 原有方式存在以下几个核心问题：</p><ol><li><strong>证书过期难以追踪</strong>：集群中存在大量服务，每个服务都有自己的 TLS 证书，缺乏集中式清单，往往在服务宕机后才发现证书已过期。</li><li><strong>密钥内嵌 spec 带来安全风险</strong>：证书和私钥直接嵌入服务 spec，一旦日志或调试输出暴露 spec，私钥将以明文泄露。</li><li><strong>手动轮换困难</strong>：需要手动查找所有使用该密钥的地方，操作繁琐且容易遗漏。</li><li><strong>命名不一致</strong>：不同服务（如 RGW、NVMeoF）使用不同字段名来配置证书，缺乏统一规范，给用户带来困惑。</li></ol><h2 id="certmgr-的设计目标与核心功能" tabindex="-1">certmgr 的设计目标与核心功能 <a class="header-anchor" href="#certmgr-的设计目标与核心功能" aria-label="Permalink to &quot;certmgr 的设计目标与核心功能&quot;">​</a></h2><p>certmgr 作为 Cephadm 的子组件，以如下方式解决上述问题：</p><ul><li><strong>充当自签证书的根 CA</strong>：自动为 Ceph 集群内各服务签发自签证书。</li><li><strong>自动续签</strong>：检测到证书即将过期时，自动触发续签流程并重新部署服务，无需人工介入。</li><li><strong>证书合法性校验</strong>：对用户提供的证书和密钥进行解析和验证，确保密钥对匹配、证书未过期。</li><li><strong>集中式证书存储</strong>：所有证书统一存储在 Mon DB 中，certmgr 充当集群内证书的中央清单。</li><li><strong>智能决策</strong>：根据证书来源（自签 vs 用户提供）和证书状态，决定是自动修复还是发出告警让运维介入。</li></ul><h2 id="证书分类" tabindex="-1">证书分类 <a class="header-anchor" href="#证书分类" aria-label="Permalink to &quot;证书分类&quot;">​</a></h2><p>Ceph 集群中的证书按作用域分为三类：</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>示例服务</th></tr></thead><tbody><tr><td>全局（global）</td><td>整个集群只有一个实例</td><td>Management Gateway、Cephadm root CA</td></tr><tr><td>按主机（per host）</td><td>每台主机一个证书</td><td>Grafana、Prometheus 监控栈</td></tr><tr><td>按服务（per service）</td><td>每个服务实例一个证书</td><td>RGW、NFS、NVMeoF</td></tr></tbody></table><p>certmgr 能自动识别证书类型，并为不同类型执行正确的签发和续签逻辑。</p><h2 id="统一的字段命名规范" tabindex="-1">统一的字段命名规范 <a class="header-anchor" href="#统一的字段命名规范" aria-label="Permalink to &quot;统一的字段命名规范&quot;">​</a></h2><p>为解决命名不一致问题，certmgr 引入了跨服务统一的字段规范：</p><ul><li><strong><code>ssl</code></strong>：布尔值，用于开启或关闭 TLS。</li><li><strong><code>ssl_cert</code> / <code>ssl_key</code></strong>：证书和密钥字段。</li><li><strong><code>ssl_cert_source</code></strong>：新增字段，指定证书来源，取值如下： <ul><li><code>inline</code>：兼容旧方式，证书和密钥直接内嵌在 spec 中。</li><li><code>reference</code>：证书存放在 certmgr store 中，spec 里只保存引用，避免密钥明文暴露。</li><li><code>cephadm_signed</code>（默认）：由 certmgr 自动生成和管理，无需用户提供任何证书。</li></ul></li></ul><p>使用示例——以最简方式为 RGW 启用 TLS：只需在 spec 中设置 <code>ssl: true</code>，certmgr 会自动完成证书的生成和部署。</p><h2 id="配置参数" tabindex="-1">配置参数 <a class="header-anchor" href="#配置参数" aria-label="Permalink to &quot;配置参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th><th>默认值</th></tr></thead><tbody><tr><td><code>check_period</code></td><td>检查证书的频率</td><td>每天一次</td></tr><tr><td><code>auto_rotate</code></td><td>是否启用自签证书的自动轮换</td><td>可配置</td></tr><tr><td><code>renewal_window</code></td><td>提前多久发出即将过期告警</td><td>可配置（示例：1 个月）</td></tr><tr><td><code>cert_duration</code></td><td>证书有效期</td><td>3 年（可按公司安全要求调整）</td></tr></tbody></table><h2 id="证书验证与状态分类" tabindex="-1">证书验证与状态分类 <a class="header-anchor" href="#证书验证与状态分类" aria-label="Permalink to &quot;证书验证与状态分类&quot;">​</a></h2><p>每次用户提交新 spec，certmgr 会对证书进行完整的验证流水线，并将状态分为以下几类：</p><ul><li><strong>Valid</strong>：证书有效，可正常使用。</li><li><strong>Expiring Soon</strong>：证书即将过期，发出告警提醒用户及时轮换。</li><li><strong>Expired</strong>：证书已过期（可能是误操作放入了错误的证书）。</li><li><strong>Invalid</strong>：证书与密钥不匹配，服务无法正常启动。</li></ul><h2 id="自动修复决策逻辑" tabindex="-1">自动修复决策逻辑 <a class="header-anchor" href="#自动修复决策逻辑" aria-label="Permalink to &quot;自动修复决策逻辑&quot;">​</a></h2><p>certmgr 在检测到问题后，根据证书来源执行不同策略：</p><p><strong>用户提供的证书（user-provided）：</strong></p><ul><li>即将过期 → 发出 health warning</li><li>已过期 → 发出 health error</li></ul><p><strong>自签证书（self-signed）：</strong></p><ul><li>Invalid → 自动覆盖，重新生成并重新部署服务</li><li>即将过期 → 自动续签并重新部署，无需人工介入</li></ul><h2 id="health-告警与-dashboard-集成" tabindex="-1">Health 告警与 Dashboard 集成 <a class="header-anchor" href="#health-告警与-dashboard-集成" aria-label="Permalink to &quot;Health 告警与 Dashboard 集成&quot;">​</a></h2><p><strong>Health 告警示例：</strong> 当 certmgr 检测到证书问题时，会在 Ceph health 状态中显示详细信息，例如：</p><ul><li><code>ceph-node-0</code> 上的 Grafana 证书已过期</li><li>Management Gateway 的证书无效（cert 与 key 不匹配）</li></ul><p><strong>新增 CLI 命令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 列出所有证书</span></span>
<span class="line"><span>ceph orch certmgr cert ls</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看证书详情（含 cephadm 自签证书）</span></span>
<span class="line"><span>ceph orch certmgr cert show --include-cephadm-signed</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 按 scope 和状态过滤</span></span>
<span class="line"><span>ceph orch certmgr cert ls --scope service --status expiring</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查看密钥列表</span></span>
<span class="line"><span>ceph orch certmgr key ls</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 查询服务对应的证书名称（适用于 NVMeoF 等多证书服务）</span></span>
<span class="line"><span>ceph orch certmgr cert names &lt;service&gt;</span></span></code></pre></div><p><strong>Dashboard 集成：</strong></p><ul><li>服务列表新增&quot;证书状态&quot;列，可直观查看各服务证书健康情况。</li><li>已对接 Prometheus alert 系统，证书异常时自动触发告警，告警详情包含异常证书所在主机和来源类型。</li></ul><h2 id="q-a-环节重点" tabindex="-1">Q&amp;A 环节重点 <a class="header-anchor" href="#q-a-环节重点" aria-label="Permalink to &quot;Q&amp;A 环节重点&quot;">​</a></h2><p><strong>Q：是否计划集成 ACME 协议以实现用户证书的自动续签？</strong></p><p>A：ACME 集成在技术上可行，但存在挑战：</p><ul><li>HTTP challenge 需要 Cephadm 在端口 80 启动监听服务，存在&quot;鸡生蛋&quot;的循环依赖问题。</li><li>DNS challenge 需要控制 DNS 记录，基础设施要求更高，实现更复杂。</li><li>代码已在设计上预留了 ACME 集成接口，当前发出 warning 的地方未来可替换为调用 ACME 续签流程。</li><li>目前尚未实现，但列入规划。</li></ul><p><strong>Q：证书有效期（duration）的默认值是否可以缩短？</strong></p><p>A：默认有效期在设计时参考了 Let&#39;s Encrypt 的建议值，当前默认 3 年。可通过 <code>cert_duration</code> 参数自定义，未来版本可能调整默认值。</p><p><strong>Q：是否支持将 certmgr 生成的 CA 作为企业内部根 CA 的下级 CA（sub-CA）？</strong></p><p>A：已有相关 PR 在进行中，支持用户提供自己的 CA 来签发自签证书，而不是使用 certmgr 生成的根 CA。这是多位用户的共同需求，会加快推进。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>certmgr 通过以下几个维度系统性地提升了 Ceph 集群的 TLS 管理体验：</p><ol><li><strong>安全性</strong>：证书不再内嵌 spec，私钥不再明文暴露。</li><li><strong>自动化</strong>：自签证书全生命周期自动管理，无需人工干预。</li><li><strong>可观测性</strong>：集中式证书清单 + Dashboard 集成 + 告警系统，证书状态一目了然。</li><li><strong>一致性</strong>：统一的字段命名规范，降低用户配置门槛。</li></ol><p>对于已在使用 Cephadm 的用户，升级到 Squid 版本后可直接受益于 certmgr 的完整功能；对于仍使用包部署方式的用户，certmgr 也是迁移到 Cephadm 的又一个有力理由。</p>`,46)])])}const m=t(s,[["render",i]]);export{g as __pageData,m as default};
